import{_ as e,o,c as r,a2 as a}from"./chunks/framework.CS-cBh1g.js";const u=JSON.parse('{"title":"Projects, files and settings","description":"","frontmatter":{},"headers":[],"relativePath":"suite/projects.md","filePath":"suite/projects.md"}'),s={name:"suite/projects.md"};function n(i,t,d,l,p,c){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="projects-files-and-settings" tabindex="-1">Projects, files and settings <a class="header-anchor" href="#projects-files-and-settings" aria-label="Permalink to &quot;Projects, files and settings&quot;">​</a></h1><h2 id="projects" tabindex="-1">Projects <a class="header-anchor" href="#projects" aria-label="Permalink to &quot;Projects&quot;">​</a></h2><p>Click the <strong>project name</strong> in the top bar to create, rename, duplicate, open or switch projects. Each project holds its robot limits, routines, typed inputs and state-machine manifests. <strong>Export project</strong> (in the same menu) downloads a portable JSON backup; the upload button next to the name imports one.</p><p>Projects use the <code>mayhem-suite</code> version 1 JSON format. In a robot repo the project is <code>robot.mayhem.json</code> at the root; choosing that folder opens it. See <a href="/Mayhem/reference/repo-files">the tools/mayhem folder</a>.</p><h3 id="live-file-link-desktop" tabindex="-1">Live file link (desktop) <a class="header-anchor" href="#live-file-link-desktop" aria-label="Permalink to &quot;Live file link (desktop)&quot;">​</a></h3><p><strong>Settings → Agents and the project file → Save project file</strong> writes the project into your robot repository and keeps it linked:</p><ul><li>App edits save back to the file.</li><li>Edits made outside the app (by you or an agent) reload automatically, with a revision check.</li><li>If a conflict banner appears, export your current work, then reopen the file and reconcile.</li></ul><p>In the browser, <strong>Download project file</strong> saves a one-time snapshot instead.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>Open with the gear in the top bar.</p><table tabindex="0"><thead><tr><th>Panel</th><th>What&#39;s there</th></tr></thead><tbody><tr><td><strong>Appearance</strong></td><td>Light, Dark or Match system. The sun/moon button in the top bar toggles it too.</td></tr><tr><td><strong>Keyboard shortcuts</strong></td><td>The full list (also <code>?</code> in Autonomous).</td></tr><tr><td><strong>Updates</strong></td><td>Version and update check. A banner appears when a release is out; <strong>Install</strong> restarts into it.</td></tr><tr><td><strong>Recovery</strong></td><td><strong>Export recovery snapshot</strong> downloads the last saved copy if a project was ever damaged.</td></tr></tbody></table>',11)])])}const g=e(s,[["render",n]]);export{u as __pageData,g as default};
